export type StatusTimeReportWritable = {
    /**
     * The start of the window, RFC 3339. Empty when the whole history is counted.
     */
    from?: string;
    group_by?: string;
    /**
     * The same per assignee or label, largest first. Empty without group_by.
     */
    groups?: Array<StatusTimeGroup> | null;
    /**
     * True when a task can be part of several groups.
     */
    multi_valued?: boolean;
    /**
     * Every status the tasks were in, in the order of the workflow.
     */
    statuses?: Array<StatusTimeStat> | null;
    /**
     * The number of tasks that were counted.
     */
    tasks?: number;
    timezone?: string;
    /**
     * The end of the window, RFC 3339. Open visits are counted until then.
     */
    to?: string;
    /**
     * True when groups beyond the limit were left out.
     */
    truncated?: boolean;
};

export type StatusTimeRequestWritable = {
    /**
     * A task filter, the same syntax as in views, incl. status, status_category and cf_<id>.
     */
    filter?: string;
    /**
     * If true, tasks whose filtered field is empty are included.
     */
    filter_include_nulls?: boolean;
    /**
     * Only count time after this moment: an RFC 3339 timestamp, a date like 2026-01-31, or now-90d. All of the history when omitted.
     */
    from?: string;
    /**
     * Also split the result by assignee or label. A task with several of them counts in each group.
     */
    group_by?: 'assignee' | 'label';
    /**
     * With group_by: keep this many groups, the ones with the most tasks (20 when omitted).
     */
    limit?: number;
    /**
     * The project: statuses belong to the workflow of one project.
     */
    project_id?: number;
    /**
     * An IANA time zone that plain dates are read in. Defaults to the time zone setting of the user.
     */
    timezone?: string;
    /**
     * Only count time before this moment, same formats as from, now when omitted. A plain date includes that day. Later moments are cut to now.
     */
    to?: string;
};

export type TaskWritable = {
    /**
     * The bucket the task is in. Only populated when the task is accessed via a view with buckets. To move a task between buckets, the new bucket must be in the same view as the old one.
     */
    bucket_id?: number;
    /**
     * The id of the attachment used as this task's cover image, or 0 for none.
     */
    cover_image_attachment_id?: number;
    description?: string;
    done?: boolean;
    due_date?: string;
    end_date?: string;
    /**
     * The task color as a hex string without the leading '#'.
     */
    hex_color?: string;
    /**
     * Whether the requesting user has favorited this task. Per-user, so it differs between callers.
     */
    is_favorite?: boolean;
    /**
     * How far the task is from done, between 0 and 1.
     */
    percent_done?: number;
    priority?: number;
    /**
     * The id of the project this task belongs to. On create it is taken from the URL; on update, setting it to a different project moves the task (requires write access to the target project).
     */
    project_id?: number;
    reminders?: Array<TaskReminder> | null;
    /**
     * The interval in seconds this task repeats. When set, marking the task done re-opens it and bumps its reminders and due date by this amount.
     */
    repeat_after?: number;
    /**
     * How the task repeats when marked done: 0 = after repeat_after seconds, 1 = monthly (ignores repeat_after), 2 = from the current date rather than the last set date.
     */
    repeat_mode?: number;
    start_date?: string;
    /**
     * The task title. This is what you'll see in the project.
     */
    title?: string;
};

